/**
 * M3 Theme Token Generator
 *
 * Reads seed colors from package.json "theme" field and generates
 * Material Design 3 tonal palettes as CSS custom properties.
 *
 * Output: app/assets/css/material-tokens.css
 *
 * DO NOT EDIT the output file — it is regenerated by this script.
 */

import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs'
import { resolve, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import {
  argbFromHex,
  hexFromArgb,
  TonalPalette,
  Hct,
} from '@material/material-color-utilities'

const __filename = fileURLToPath(import.meta.url)
const __dirname = dirname(__filename)
const ROOT = resolve(__dirname, '..')

// --- Configuration ---

const TONAL_STOPS = [
  0, 4, 6, 10, 12, 17, 20, 22, 24, 25, 30, 35, 40, 50, 60, 70, 80, 87, 90,
  92, 94, 95, 96, 98, 99, 100,
]

const COLOR_ROLES = [
  'primary',
  'secondary',
  'tertiary',
  'neutral',
  'neutral-variant',
  'error',
]

// M3 semantic role mappings: [token-name, palette-source, light-tone, dark-tone]
const SEMANTIC_ROLES = [
  ['primary', 'primary', 40, 80],
  ['on-primary', 'primary', 100, 20],
  ['primary-container', 'primary', 90, 30],
  ['on-primary-container', 'primary', 10, 90],
  ['secondary', 'secondary', 40, 80],
  ['on-secondary', 'secondary', 100, 20],
  ['secondary-container', 'secondary', 90, 30],
  ['on-secondary-container', 'secondary', 10, 90],
  ['tertiary', 'tertiary', 40, 80],
  ['on-tertiary', 'tertiary', 100, 20],
  ['tertiary-container', 'tertiary', 90, 30],
  ['on-tertiary-container', 'tertiary', 10, 90],
  ['error', 'error', 40, 80],
  ['on-error', 'error', 100, 20],
  ['error-container', 'error', 90, 30],
  ['on-error-container', 'error', 10, 90],
  ['surface', 'neutral', 99, 10],
  ['on-surface', 'neutral', 10, 90],
  ['surface-variant', 'neutral-variant', 90, 30],
  ['on-surface-variant', 'neutral-variant', 30, 80],
  ['outline', 'neutral-variant', 50, 60],
  ['outline-variant', 'neutral-variant', 80, 30],
  ['inverse-surface', 'neutral', 20, 90],
  ['inverse-on-surface', 'neutral', 95, 20],
  ['inverse-primary', 'primary', 80, 40],
]

// --- Validation ---

const HEX_REGEX = /^#[0-9a-fA-F]{6}$/

function validateHex(value, name) {
  if (!HEX_REGEX.test(value)) {
    console.error(
      `Error: Invalid seed color for "${name}": "${value}" is not a valid 6-character hex color code (expected format: #RRGGBB).`
    )
    process.exit(1)
  }
}

// --- Palette Generation ---

function createTonalPalette(hexColor) {
  const argb = argbFromHex(hexColor)
  const hct = Hct.fromInt(argb)
  return TonalPalette.fromHueAndChroma(hct.hue, hct.chroma)
}

function getToneHex(palette, tone) {
  return hexFromArgb(palette.tone(tone))
}

// --- Main ---

function main() {
  // Read package.json
  const pkgPath = resolve(ROOT, 'package.json')
  const pkg = JSON.parse(readFileSync(pkgPath, 'utf-8'))
  const theme = pkg.theme

  if (!theme) {
    console.error('Error: No "theme" field found in package.json.')
    process.exit(1)
  }

  // Validate seed colors
  const requiredSeeds = ['primary', 'secondary', 'tertiary']
  for (const seed of requiredSeeds) {
    if (!theme[seed]) {
      console.error(
        `Error: Missing seed color "${seed}" in package.json "theme" field.`
      )
      process.exit(1)
    }
    validateHex(theme[seed], seed)
  }

  // Generate tonal palettes
  const palettes = {
    primary: createTonalPalette(theme.primary),
    secondary: createTonalPalette(theme.secondary),
    tertiary: createTonalPalette(theme.tertiary),
  }

  // Neutral palette: derived from primary with low chroma
  const primaryArgb = argbFromHex(theme.primary)
  const primaryHct = Hct.fromInt(primaryArgb)
  palettes['neutral'] = TonalPalette.fromHueAndChroma(primaryHct.hue, 4)
  palettes['neutral-variant'] = TonalPalette.fromHueAndChroma(
    primaryHct.hue,
    8
  )

  // Error palette: fixed red hue
  palettes['error'] = TonalPalette.fromHueAndChroma(25, 84)

  // Build CSS output
  let css = '/* AUTO-GENERATED by scripts/generate-theme.mjs — DO NOT EDIT */\n\n'

  // Tonal palette tokens for :root (light)
  css += ':root {\n'
  css += '  /* Tonal palette stops */\n'
  for (const role of COLOR_ROLES) {
    for (const stop of TONAL_STOPS) {
      const hex = getToneHex(palettes[role], stop)
      css += `  --md-ref-palette-${role}-${stop}: ${hex};\n`
    }
    css += '\n'
  }

  // Semantic light tokens
  css += '  /* M3 semantic color roles — light */\n'
  for (const [name, source, lightTone] of SEMANTIC_ROLES) {
    const hex = getToneHex(palettes[source], lightTone)
    css += `  --md-sys-color-${name}: ${hex};\n`
  }
  css += '}\n\n'

  // Dark mode tokens
  css += '.dark {\n'
  css += '  /* M3 semantic color roles — dark */\n'
  for (const [name, source, , darkTone] of SEMANTIC_ROLES) {
    const hex = getToneHex(palettes[source], darkTone)
    css += `  --md-sys-color-${name}: ${hex};\n`
  }
  css += '}\n'

  // Write output
  const outputDir = resolve(ROOT, 'app', 'assets', 'css')
  if (!existsSync(outputDir)) {
    mkdirSync(outputDir, { recursive: true })
  }

  const outputPath = resolve(outputDir, 'material-tokens.css')
  writeFileSync(outputPath, css, 'utf-8')

  console.log(`✓ Generated ${outputPath}`)
  console.log(
    `  ${COLOR_ROLES.length} palettes × ${TONAL_STOPS.length} stops = ${COLOR_ROLES.length * TONAL_STOPS.length} tonal tokens`
  )
  console.log(`  ${SEMANTIC_ROLES.length} semantic tokens (light + dark)`)
}

main()
